-- 사용자 여정 퍼널 확정 이탈 기준 변경 (2026-10-01)
--  1) '여행 생성'과 '설문 완료'를 한 단계로 합침: 여행 생성 화면에서 설문까지 한 번에 저장하므로
--     설문만 빠진 여행은 생기지 않음. reached_step 은 CREATED 부터, drop_step 에서 SURVEYED 없음.
--  2) 계획 단계(추천 받음·장소 담음·모두 배치·일정 확정)는 출발일이 지나도록 다음 단계로 못 가면 확정 이탈
--     (기존: 종료일이 지나야 이탈)
--  3) 후기 단계는 그대로 종료일 + 14일 (후기는 종료일부터 작성 가능, 에어비앤비 후기 기한과 같은 14일)
-- 이미 만든 DB에서 한 번만 실행 (새로 만드는 DB는 DB/jejuro_routines.sql 에 같은 뷰가 들어 있음).
-- Workbench에서 Spring이 쓰는 DB를 고른 뒤 실행하세요.

CREATE OR REPLACE VIEW `travel_funnel` AS with `base` as (select `t`.`travel_id` AS `travel_id`,`t`.`user_id` AS `user_id`,`t`.`created_at` AS `created_at`,`t`.`start_date` AS `start_date`,`t`.`end_date` AS `end_date`,exists(select 1 from `travel_preference` `tp` where (`tp`.`travel_id` = `t`.`travel_id`)) AS `s_surveyed`,exists(select 1 from `recommend_request` `q` where ((`q`.`travel_id` = `t`.`travel_id`) and (`q`.`status` = 'SUCCESS'))) AS `s_recommended`,(select count(0) from `travel_bookmark` `b` where (`b`.`travel_id` = `t`.`travel_id`)) AS `place_count`,(select count(0) from `travel_bookmark` `b` where ((`b`.`travel_id` = `t`.`travel_id`) and exists(select 1 from ((`travel_route` `rt` join `route_day` `rd` on((`rd`.`route_id` = `rt`.`route_id`))) join `route_spot` `s` on((`s`.`route_day_id` = `rd`.`route_day_id`))) where ((`rt`.`travel_id` = `t`.`travel_id`) and (`s`.`poi_id` = `b`.`poi_id`))))) AS `placed_count`,(`t`.`adopted_route_id` is not null) AS `s_adopted`,exists(select 1 from `travel_feedback` `f` where (`f`.`travel_id` = `t`.`travel_id`)) AS `s_reviewed`,exists(select 1 from `community_post` `cp` where ((`cp`.`travel_id` = `t`.`travel_id`) and (`cp`.`deleted_at` is null))) AS `s_shared` from `travel` `t` where (`t`.`source_post_id` is null)), `steps` as (select `b`.`travel_id` AS `travel_id`,`b`.`user_id` AS `user_id`,`b`.`created_at` AS `created_at`,`b`.`start_date` AS `start_date`,`b`.`end_date` AS `end_date`,`b`.`s_surveyed` AS `s_surveyed`,`b`.`s_recommended` AS `s_recommended`,`b`.`place_count` AS `place_count`,`b`.`placed_count` AS `placed_count`,`b`.`s_adopted` AS `s_adopted`,`b`.`s_reviewed` AS `s_reviewed`,`b`.`s_shared` AS `s_shared`,(`b`.`place_count` > 0) AS `s_placed_any`,((`b`.`place_count` > 0) and (`b`.`placed_count` = `b`.`place_count`)) AS `s_placed_all`,(case when `b`.`s_reviewed` then 7 when `b`.`s_adopted` then 6 when ((`b`.`place_count` > 0) and (`b`.`placed_count` = `b`.`place_count`)) then 5 when (`b`.`place_count` > 0) then 4 when `b`.`s_recommended` then 3 when `b`.`s_surveyed` then 2 else 1 end) AS `reached_no` from `base` `b`) select `steps`.`travel_id` AS `travel_id`,`steps`.`user_id` AS `user_id`,`steps`.`created_at` AS `created_at`,`steps`.`start_date` AS `start_date`,`steps`.`end_date` AS `end_date`,1 AS `step_created`,`steps`.`s_surveyed` AS `step_surveyed`,`steps`.`s_recommended` AS `step_recommended`,`steps`.`s_placed_any` AS `step_placed_any`,`steps`.`s_placed_all` AS `step_placed_all`,`steps`.`s_adopted` AS `step_adopted`,`steps`.`s_reviewed` AS `step_reviewed`,`steps`.`s_shared` AS `step_shared`,`steps`.`place_count` AS `place_count`,`steps`.`placed_count` AS `placed_count`,elt(`steps`.`reached_no`,'CREATED','CREATED','RECOMMENDED','PLACED_ANY','PLACED_ALL','ADOPTED','REVIEWED') AS `reached_step`,(case when (`steps`.`reached_no` = 7) then 'DONE' when ((`steps`.`reached_no` < 6) and (`steps`.`start_date` < curdate())) then 'DROPPED' when ((`steps`.`reached_no` = 6) and (`steps`.`end_date` < (curdate() - interval 14 day))) then 'DROPPED' else 'IN_PROGRESS' end) AS `funnel_status`,(case when (((`steps`.`reached_no` < 6) and (`steps`.`start_date` < curdate())) or ((`steps`.`reached_no` = 6) and (`steps`.`end_date` < (curdate() - interval 14 day)))) then elt(`steps`.`reached_no`,'RECOMMENDED','RECOMMENDED','PLACED_ANY','PLACED_ALL','ADOPTED','REVIEWED') end) AS `drop_step` from `steps`;